// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testRegression_property() public {
        address owner = address(this);
        address target = address(0x1234);

        vm.deal(owner, 1 ether);
        bytes memory empty;
        vm.prank(owner);
        c.Command{value: 1}(target, empty);

        vm.prank(owner);
        c.multiplicate{value: 0}(target);

        assertTrue(address(c).balance == 0);
    }
}
